// A loan checked in at the desk: fined for the days it is late, and the fine charged to its member.
export function returnedAtDesk(store, tenant, loan, day) {
  const copy = mine(store, tenant, "copies", loan.copy);
  const fineCents = fineFor(titleOfCopy(store, copy), copy, loan.due, day);
  charged(store, mine(store, tenant, "members", loan.member), fineCents);
  return put(store, "loans", { ...returned(store, tenant, loan, day), fineCents });
}
